package com.irwi.fincapp.ui;
import android.app.*;import android.os.*;import android.content.*;import android.database.*;import android.widget.*;import com.irwi.fincapp.repository.FarmRepository;import com.irwi.fincapp.session.SessionManager;
public class FarmActivity extends Activity{public void onCreate(Bundle b){super.onCreate(b);LinearLayout l=BaseUi.root(this);l.addView(BaseUi.title(this,"Select farm"));l.addView(BaseUi.text(this,"Choose active farm for offline records.",18));Cursor c=new FarmRepository(this).farms();try{while(c.moveToNext()){String id=c.getString(0), name=c.getString(1), loc=c.getString(2);Button btn=BaseUi.btn(this,"🏡 "+name+"\n"+loc);l.addView(btn);btn.setOnClickListener(v->{new SessionManager(this).setFarm(id,name);startActivity(new Intent(this,HomeActivity.class));finish();});}}finally{c.close();}Button settings=BaseUi.btn(this,"Settings");l.addView(settings);settings.setOnClickListener(v->startActivity(new Intent(this,SettingsActivity.class)));}}
